import io
import pickle

import pytest
import torch


try:
    from safetensors.torch import save
except ImportError:
    save = None


class TestCompressedStorageBenchmark:
    """Benchmark tests for CompressedListStorage."""

    @staticmethod
    def make_compressible_mock_data(num_experiences: int, device=None) -> dict:
        """Easily compressible data for testing."""
        if device is None:
            device = torch.device("cpu")

        return {
            "observations": torch.zeros(
                (num_experiences, 4, 84, 84),
                dtype=torch.uint8,
                device=device,
            ),
            "actions": torch.zeros((num_experiences,), device=device),
            "rewards": torch.zeros((num_experiences,), device=device),
            "next_observations": torch.zeros(
                (num_experiences, 4, 84, 84),
                dtype=torch.uint8,
                device=device,
            ),
            "terminations": torch.zeros(
                (num_experiences,), dtype=torch.bool, device=device
            ),
            "truncations": torch.zeros(
                (num_experiences,), dtype=torch.bool, device=device
            ),
            "batch_size": [num_experiences],
        }

    @staticmethod
    def make_uncompressible_mock_data(num_experiences: int, device=None) -> dict:
        """Uncompressible data for testing."""
        if device is None:
            device = torch.device("cpu")
        return {
            "observations": torch.randn(
                (num_experiences, 4, 84, 84),
                dtype=torch.float32,
                device=device,
            ),
            "actions": torch.randint(0, 10, (num_experiences,), device=device),
            "rewards": torch.randn(
                (num_experiences,), dtype=torch.float32, device=device
            ),
            "next_observations": torch.randn(
                (num_experiences, 4, 84, 84),
                dtype=torch.float32,
                device=device,
            ),
            "terminations": torch.rand((num_experiences,), device=device)
            < 0.2,  # ~20% True
            "truncations": torch.rand((num_experiences,), device=device)
            < 0.1,  # ~10% True
            "batch_size": [num_experiences],
        }

    @pytest.mark.benchmark(
        group="tensor_serialization_speed",
        min_time=0.1,
        max_time=0.5,
        min_rounds=5,
        disable_gc=True,
        warmup=False,
    )
    @pytest.mark.parametrize(
        "serialization_method",
        ["pickle", "torch.save", "untyped_storage", "numpy", "safetensors"],
    )
    def test_tensor_to_bytestream_speed(self, benchmark, serialization_method: str):
        """Benchmark the speed of different tensor serialization methods.

        TODO: we might need to also test which methods work on the gpu.
        pytest benchmarks/test_compressed_storage_benchmark.py::TestCompressedStorageBenchmark::test_tensor_to_bytestream_speed -v --benchmark-only --benchmark-sort='mean' --benchmark-columns='mean, ops'

        ------------------------ benchmark 'tensor_to_bytestream_speed': 5 tests -------------------------
        Name (time in us)                                           Mean (smaller is better)   OPS (bigger is better)
        --------------------------------------------------------------------------------------------------
        test_tensor_serialization_speed[numpy]                    2.3520 (1.0)      425,162.1779 (1.0)
        test_tensor_serialization_speed[safetensors]             14.7170 (6.26)      67,948.7129 (0.16)
        test_tensor_serialization_speed[pickle]                  19.0711 (8.11)      52,435.3333 (0.12)
        test_tensor_serialization_speed[torch.save]              32.0648 (13.63)     31,186.8261 (0.07)
        test_tensor_serialization_speed[untyped_storage]     38,227.0224 (>1000.0)       26.1595 (0.00)
        --------------------------------------------------------------------------------------------------
        """

        def serialize_with_pickle(data: torch.Tensor) -> bytes:
            """Serialize tensor using pickle."""
            buffer = io.BytesIO()
            pickle.dump(data, buffer)
            return buffer.getvalue()

        def serialize_with_untyped_storage(data: torch.Tensor) -> bytes:
            """Serialize tensor using torch's built-in method."""
            return bytes(data.untyped_storage())

        def serialize_with_numpy(data: torch.Tensor) -> bytes:
            """Serialize tensor using numpy."""
            return data.numpy().tobytes()

        def serialize_with_safetensors(data: torch.Tensor) -> bytes:
            return save({"0": data})

        def serialize_with_torch(data: torch.Tensor) -> bytes:
            """Serialize tensor using torch's built-in method."""
            buffer = io.BytesIO()
            torch.save(data, buffer)
            return buffer.getvalue()

        # Benchmark each serialization method
        if serialization_method == "pickle":
            serialize_fn = serialize_with_pickle
        elif serialization_method == "torch.save":
            serialize_fn = serialize_with_torch
        elif serialization_method == "untyped_storage":
            serialize_fn = serialize_with_untyped_storage
        elif serialization_method == "numpy":
            serialize_fn = serialize_with_numpy
        elif serialization_method == "safetensors":
            serialize_fn = serialize_with_safetensors
        else:
            raise ValueError(f"Unknown serialization method: {serialization_method}")

        data = self.make_compressible_mock_data(1).get("observations")

        # Run the actual benchmark
        benchmark(serialize_fn, data)

"""Benchmarks for StoreStorage vs LazyTensorStorage.

Run with:
    pytest test/test_benchmark_store_storage.py --benchmark-only -v
    pytest test/test_benchmark_store_storage.py --benchmark-only --benchmark-group-by=param:storage_type
"""

import importlib

import pytest
import torch
from tensordict import TensorDict

from torchrl.data import ReplayBuffer
from torchrl.data.replay_buffers import LazyTensorStorage, StoreStorage
from torchrl.data.replay_buffers.samplers import RandomSampler
from torchrl.data.replay_buffers.writers import RoundRobinWriter

_has_redis = importlib.util.find_spec("redis") is not None
pytestmark = pytest.mark.skipif(not _has_redis, reason="redis not available")

BUFFER_SIZE = 10_000
OBS_DIM = 64
ACTION_DIM = 4
BATCH_SIZE = 256
FILL_CHUNK = 500


def _flush_redis():
    import redis

    r = redis.Redis()
    r.flushdb()
    r.close()


def _make_batch(n: int) -> TensorDict:
    return TensorDict(
        {
            "obs": torch.randn(n, OBS_DIM),
            "action": torch.randn(n, ACTION_DIM),
            "reward": torch.randn(n, 1),
        },
        batch_size=[n],
    )


def _make_rb(storage_type: str, prefetch: int = 0) -> ReplayBuffer:
    kwargs = {}
    if prefetch:
        kwargs["prefetch"] = prefetch
    if storage_type == "lazy_tensor":
        storage = LazyTensorStorage(max_size=BUFFER_SIZE)
    else:
        storage = StoreStorage(max_size=BUFFER_SIZE)
    return ReplayBuffer(
        storage=storage,
        sampler=RandomSampler(),
        writer=RoundRobinWriter(),
        batch_size=BATCH_SIZE,
        **kwargs,
    )


def _prefill(rb: ReplayBuffer, n: int = 5000):
    remaining = min(n, BUFFER_SIZE)
    while remaining > 0:
        chunk = min(FILL_CHUNK, remaining)
        rb.extend(_make_batch(chunk))
        remaining -= chunk


@pytest.fixture(autouse=True)
def flush_redis():
    _flush_redis()
    yield
    _flush_redis()


@pytest.mark.parametrize("storage_type", ["lazy_tensor", "store"])
def test_fill(benchmark, storage_type):
    rb = _make_rb(storage_type)

    def _fill():
        _prefill(rb, n=5000)

    benchmark.pedantic(_fill, rounds=3, warmup_rounds=1)


@pytest.mark.parametrize("storage_type", ["lazy_tensor", "store"])
def test_sample(benchmark, storage_type):
    rb = _make_rb(storage_type)
    _prefill(rb)

    benchmark(rb.sample)


@pytest.mark.parametrize("storage_type", ["lazy_tensor", "store"])
def test_sample_prefetch(benchmark, storage_type):
    rb = _make_rb(storage_type, prefetch=4)
    _prefill(rb)

    benchmark(rb.sample)

from __future__ import annotations

import importlib.util
import json
from pathlib import Path

import pytest


_REPO_ROOT = Path(__file__).parents[2]


def _load_script(name: str):
    path = _REPO_ROOT / ".github" / "scripts" / name
    spec = importlib.util.spec_from_file_location(path.stem, path)
    assert spec is not None
    assert spec.loader is not None
    module = importlib.util.module_from_spec(spec)
    spec.loader.exec_module(module)
    return module


comparison = _load_script("compare_pr_benchmarks.py")
comments = _load_script("comment_pr_benchmarks.py")
async_summary = _load_script("summarize_async_benchmarks.py")


def _document(durations_by_name: dict[str, float]) -> dict:
    return {
        "benchmarks": [
            {
                "fullname": name,
                "stats": {
                    "mean": duration,
                    "median": duration,
                    "ops": 1.0 / duration,
                },
            }
            for name, duration in durations_by_name.items()
        ]
    }


def _metadata(device: str, revision: str) -> dict:
    return {
        "device": device,
        "revision": revision,
        "sha": "base-sha" if revision == "baseline" else "head-sha",
        "pr_number": 123,
        "base_sha": "base-sha",
        "head_sha": "head-sha",
        "runner": "pinned-runner",
        "image": "pinned-image",
        "python_version": "3.10.20",
        "system_environment_sha256": "system-environment",
        "dependency_lock_sha256": "dependency-lock",
        "dependency_environment_sha256": "dependency-environment",
        "benchmark_definitions_source_sha": "base-sha",
        "benchmark_definitions_sha256": "benchmark-definitions",
        "benchmark_command": "pinned-command",
        "benchmark_environment": {"PYTHONHASHSEED": "0"},
        "run_id": "run-id",
    }


def _write_raw_pair(root: Path) -> None:
    device_root = root / "CPU"
    device_root.mkdir(parents=True)
    (device_root / "baseline.json").write_text(
        json.dumps(
            _document(
                {
                    "test_bench.py::test_regression": 0.010,
                    "test_bench.py::test_improvement": 0.010,
                }
            )
        ),
        encoding="utf-8",
    )
    (device_root / "contender.json").write_text(
        json.dumps(
            _document(
                {
                    "test_bench.py::test_regression": 1.0 / 90.0,
                    "test_bench.py::test_improvement": 1.0 / 108.0,
                }
            )
        ),
        encoding="utf-8",
    )
    for revision in ("baseline", "contender"):
        (device_root / f"{revision}-metadata.json").write_text(
            json.dumps(_metadata("CPU", revision)), encoding="utf-8"
        )


def test_comparison_prefers_median_over_mean_and_ops():
    baseline = {
        "benchmarks": [
            {
                "fullname": "test_bench.py::test_stall",
                "stats": {"median": 1.0, "mean": 1.0, "ops": 1.0},
            }
        ]
    }
    contender = {
        "benchmarks": [
            {
                "fullname": "test_bench.py::test_stall",
                "stats": {"median": 1.0, "mean": 10.0, "ops": 0.1},
            }
        ]
    }

    [row] = comparison.comparison_rows(baseline, contender)
    assert row["baseline_ops"] == pytest.approx(1.0)
    assert row["contender_ops"] == pytest.approx(1.0)
    assert row["change"] == pytest.approx(0.0)


def test_compare_writes_single_measurement_results(tmp_path):
    raw_root = tmp_path / "raw"
    output_root = tmp_path / "output"
    summary_path = tmp_path / "summary.md"
    _write_raw_pair(raw_root)

    comparison.compare_results(
        raw_root,
        output_root,
        summary_path,
        {"CPU": "pinned-image"},
        reporting_threshold=5.0,
    )

    result = json.loads(
        (output_root / "CPU" / "comparison.json").read_text(encoding="utf-8")
    )
    rows = {row["name"]: row for row in result["benchmarks"]}
    assert rows["test_bench.py::test_regression"]["change"] == pytest.approx(-10.0)
    assert rows["test_bench.py::test_improvement"]["change"] == pytest.approx(8.0)
    assert {row["measurement"] for row in rows.values()} == {"separate-pinned-runners"}

    final_metadata = json.loads(
        (output_root / "CPU" / "metadata.json").read_text(encoding="utf-8")
    )
    assert final_metadata["comparison_statistic"] == "median duration"
    assert final_metadata["measurements_per_revision"] == 1
    assert "confirmed_benchmarks" not in final_metadata
    summary = summary_path.read_text(encoding="utf-8")
    assert "once on a separate pinned runner" in summary

    _, body = comments.build_comment(
        [
            {
                "metadata": final_metadata,
                "baseline": json.loads(
                    (output_root / "CPU" / "baseline.json").read_text(encoding="utf-8")
                ),
                "contender": json.loads(
                    (output_root / "CPU" / "contender.json").read_text(encoding="utf-8")
                ),
            }
        ],
        "https://example.com/run",
    )
    assert "once on a separate pinned runner" in body
    assert "inverse median round duration" in body
    assert "same runner" not in body


def test_compare_rejects_mismatched_environments(tmp_path):
    raw_root = tmp_path / "raw"
    _write_raw_pair(raw_root)
    metadata_path = raw_root / "CPU" / "contender-metadata.json"
    metadata = json.loads(metadata_path.read_text(encoding="utf-8"))
    metadata["image"] = "different-image"
    metadata_path.write_text(json.dumps(metadata), encoding="utf-8")

    with pytest.raises(RuntimeError, match="metadata differs for image"):
        comparison.compare_results(
            raw_root,
            tmp_path / "output",
            tmp_path / "summary.md",
            {"CPU": "pinned-image"},
            reporting_threshold=5.0,
        )


def test_compare_rejects_unpinned_image(tmp_path):
    raw_root = tmp_path / "raw"
    _write_raw_pair(raw_root)

    with pytest.raises(RuntimeError, match="not the pinned image"):
        comparison.compare_results(
            raw_root,
            tmp_path / "output",
            tmp_path / "summary.md",
            {"CPU": "different-image"},
            reporting_threshold=5.0,
        )


def test_workflow_runs_only_four_primary_measurements():
    workflow = (_REPO_ROOT / ".github" / "workflows" / "benchmarks_pr.yml").read_text(
        encoding="utf-8"
    )

    assert workflow.count("          - device: CPU") == 2
    assert workflow.count("          - device: GPU") == 2
    assert workflow.count("            revision: baseline") == 2
    assert workflow.count("            revision: contender") == 2
    assert "\n  confirmation:" not in workflow
    assert "\n  finalize:" not in workflow
    assert "same-runner" not in workflow
    assert "needs: benchmark" in workflow


@pytest.mark.parametrize("failure", [None, "missing", "budget", "series", "execution"])
def test_async_trends_use_complete_repeated_measurements(tmp_path, failure):
    for repeat, duration in enumerate([1.0, 2.0, 4.0], 1):
        document = _document({"collection": duration})
        document["benchmarks"][0]["extra_info"] = {"transitions": 1024}
        if repeat == 3:
            if failure == "missing":
                continue
            if failure == "budget":
                document["benchmarks"][0]["extra_info"]["transitions"] = 2048
            if failure == "execution":
                document["benchmarks"][0]["extra_info"]["execution"] = "different"
            if failure == "series":
                document["benchmarks"] = []
        (tmp_path / f"async-{repeat}.json").write_text(json.dumps(document))
    summary = tmp_path / "summary.md"
    if failure:
        with pytest.raises(RuntimeError):
            async_summary.summarize(tmp_path, summary)
        assert not (tmp_path / "trend.json").exists()
        return
    async_summary.summarize(tmp_path, summary)
    [point] = json.loads((tmp_path / "trend.json").read_text())
    assert point["value"] == 512
    assert point["unit"] == "frames/s"
    assert point["range"] == "256.0-1024.0"
    assert "confidence intervals" in summary.read_text()


if __name__ == "__main__":
    pytest.main([__file__])
